Subject: [PATCH] kded: add shortcuts to switch to the next output and input
 device

There was no way to change the default audio device from the keyboard,
so switching between speakers and a headset meant opening the applet.
Add two global actions that cycle through the devices and show an OSD.

BUG: 515142
---
 src/kded/audioshortcutsservice.cpp | 46 ++++++++++++++++++++++++++++++
 src/kded/audioshortcutsservice.h   |  1 +
 2 files changed, 47 insertions(+)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..35a0c2b0 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -18,6 +18,7 @@
 #include <KPluginFactory>

 #include <PulseAudioQt/Device>
+#include <PulseAudioQt/Port>
 #include <PulseAudioQt/Server>
 #include <PulseAudioQt/Sink>
 #include <PulseAudioQt/Source>
@@ -189,6 +190,31 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
         }
     });

+    QAction *nextOutputDeviceAction = new QAction(this);
+    actions.append(nextOutputDeviceAction);
+    nextOutputDeviceAction->setObjectName(u"next_output_device"_s);
+    nextOutputDeviceAction->setText(i18n("Switch to Next Output Device"));
+    connect(nextOutputDeviceAction, &QAction::triggered, this, [this]() {
+        const auto sinks = PulseAudioQt::Context::instance()->sinks();
+        switchToNextDevice({sinks.cbegin(), sinks.cend()}, m_preferredDevice.sink());
+    });
+
+    QAction *nextInputDeviceAction = new QAction(this);
+    actions.append(nextInputDeviceAction);
+    nextInputDeviceAction->setObjectName(u"next_input_device"_s);
+    nextInputDeviceAction->setText(i18n("Switch to Next Input Device"));
+    connect(nextInputDeviceAction, &QAction::triggered, this, [this]() {
+        const auto sources = PulseAudioQt::Context::instance()->sources();
+        auto source = switchToNextDevice({sources.cbegin(), sources.cend()}, m_preferredDevice.source());
+        if (source && m_globalConfig->defaultOutputDeviceOsd()) {
+            QString icon = AudioIcon::forFormFactor(source->formFactor());
+            if (icon.isEmpty()) {
+                icon = u"audio-input-microphone"_s;
+            }
+            m_osdDBusInterface->showText(icon, nameForDevice(source));
+        }
+    });
+
     QAction *pushToTalkAction = new QAction(this);
     actions.append(pushToTalkAction);
     pushToTalkAction->setObjectName(u"push_to_talk"_s);
@@ -245,6 +271,26 @@ int AudioShortcutsService::changeVolumePercent(PulseAudioQt::Device *device, int
     return newPercent;
 }

+PulseAudioQt::Device *AudioShortcutsService::switchToNextDevice(const QList<PulseAudioQt::Device *> &devices, PulseAudioQt::Device *current)
+{
+    // Cycle through the devices the applet lists by default: skip virtual, dummy and unplugged ones
+    QList<PulseAudioQt::Device *> available;
+    for (auto device : devices) {
+        const auto ports = device->ports();
+        if (device->isVirtualDevice() || device->name() == DUMMY_OUTPUT_NAME
+            || (ports.size() == 1 && ports.first()->availability() == PulseAudioQt::Profile::Unavailable)) {
+            continue;
+        }
+        available.append(device);
+    }
+    if (available.isEmpty() || (available.size() == 1 && available.first() == current)) {
+        return nullptr;
+    }
+    auto next = available.at((available.indexOf(current) + 1) % available.size());
+    next->setDefault(true);
+    return next;
+}
+
 void AudioShortcutsService::handleDefaultSinkChange()
 {
     const PulseAudioQt::Sink *defaultSink = PulseAudioQt::Context::instance()->server()->defaultSink();
